"""Record the primary review only after content and listed visual sheets were inspected."""
import hashlib,json,subprocess,sys
from pathlib import Path
R=Path(__file__).resolve().parents[1];batch=sys.argv[1]
assert batch in ('22','23','24')
notes={
'22':['Reviewed 19 topic specifications and all 247 assessment answers: Python types and object binding, bounded loops, pure planning, file ownership, duplicate JSON keys, YAML schema differences, regex versus semantic validation, API pagination and state, HTTP retry semantics, authentication versus authorization, product capabilities, NETCONF optional datastores, RESTCONF/YANG, SNMP discontinuities and SSH completion.','Eight standalone standard-library examples execute successfully; the topic inspector runs for all 19 IDs. External protocol and vendor operations remain guided.'],
'23':['Reviewed 22 topic specifications and all 286 assessment answers: driver-specific behavior and partial writes, host-key rejection, candidate merge versus replacement, HTTP status/timeout behavior, inventory resolution, handler and repeat-run semantics, resource module scope, strict rendering, Git staged versus working content, trusted pipeline boundaries, Terraform state, IPAM races, NetBox intent and authority/conflict policies.','No external library execution, provider apply, repository publication or live device deployment is inferred from a browser result.'],
'24':['Reviewed 21 topic specifications and all 273 assessment answers: failure domains, survivor capacity, DR versus continuity, RTO clock boundaries, usable recovery-point age, active/active conflicts, fencing, load-balancer readiness, plane separation, observability signal limits, capacity runway and retirement.','The integrated design retains the original enterprise objective with topology, authority and policy matrices, capacity and recovery budgets, a guided version-controlled deployment procedure and an actual local validation/render/change/rollback rehearsal. Its deliberate RTO/RPO gaps remain explicit.']}
bundles=json.loads(subprocess.check_output(['node','tools/read-content.cjs'],cwd=R,text=True,encoding='utf-8'));ls=bundles[batch]
digest=lambda x:hashlib.sha256(json.dumps(x,ensure_ascii=False,sort_keys=True).encode()).hexdigest()
sheets=[str(p.relative_to(R)).replace('\\','/') for p in sorted((R/'docs/screenshots/automation').glob(f'batch-{batch}-review-*.jpg'))]
assert len(sheets)==(len(ls)+3)//4
report=dict(result='PASS',reviewer='Primary assistant',date='2026-10-09',reviewNotes=notes[batch]+['Primary visually inspected the listed contact sheets, including desktop, mobile and mechanism renders. Browser tests exercise all assessment reveals, three incident stages, model changes, reset, responsive themes, keyboard controls, downloads and file URLs.'],topics=[dict(id=l['id'],sha256=digest(l),questions={q['questionId']:digest(q) for q in l['exams']+l['quick']}) for l in ls],visualSheets=sheets,limits=['Authored incidents are not captured device evidence.','Browser calculations use declared inputs; no external service is controlled.','Actual local operations are limited to the owned temporary-file lab and standalone Python examples.','External platforms, libraries, real HA and enterprise deployment remain guided and unexecuted.'])
(R/f'docs/automation-primary-review-{batch}.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');print('Recorded primary review',batch)
